-- Gallery photo moderation: uploads are pending until a committee member approves them, so nothing shows publicly without review. Safe to run twice. alter table photos add column if not exists status text not null default 'pending'; update photos set status = 'approved' where status = 'pending'; alter table photos enable row level security; drop policy if exists "Public can read approved photos" on photos; create policy "Public can read approved photos" on photos for select using (status = 'approved'); drop policy if exists "Members can read own photos" on photos; create policy "Members can read own photos" on photos for select using (uploader_id = auth.uid()); drop policy if exists "Approved members can upload photos" on photos; create policy "Approved members can upload photos" on photos for insert with check (exists (select 1 from memberships m where m.profile_id = auth.uid() and m.status = 'approved')); drop policy if exists "Committee can manage photos" on photos; create policy "Committee can manage photos" on photos for all using (exists (select 1 from memberships m where m.profile_id = auth.uid() and m.role = 'committee'));
